  "ui.about.intro": "Полностью клиентский набор инструментов CTF для кодирования, криптографии и стеганографии — более 500 операций по кодированию / классическим и современным шифрам / хешированию / стеганографии / форензике / анализу. Всё выполняется локально в вашем браузере: без сети, без загрузки, без следов. Разверните, открыв index.html напрямую, запустив локальный сервер или разместив как статический сайт.",
