  "ui.rand.mouseHint": "Быстро подвигайте мышью в области ниже (или проведите пальцем); когда энтропии наберётся достаточно, нажмите «Готово».",
  "ui.rand.mousePadHint": "Подвигайте мышью в этой области…",
  "ui.rand.mouseProg": "Прогресс сбора",
