  "ui.about.langs": "Языковые версии",
  "ui.about.langsNote": "Полнота перевода интерфейса (относительно китайского исходного набора; рассчитывается при открытии этой страницы; отсутствующие строки откатываются к китайскому)",
  "op.caesar.desc": "Заданный сдвиг (encode +shift, decode -shift); режим переключает прогрессивный Цезарь (символ x сдвигается на shift±x); набор символов — только буквы или вся печатная зона ASCII 33-126 (для вариантов, где сдвигаются и не-буквы)",
  "op.spriteSheet.name": "Конвертер спрайт-листов",
  "op.spriteSheet.desc": "Спрайт-лист ↔ последовательность кадров: split разрезает сетку N×M на PNG по кадрам (по строкам, frame_000 и далее); merge собирает кадры (первый кадр в главном входе + по одному dataURL на строку в дополнениях) в сетку по кадров в строке, пустые ячейки последнего ряда прозрачны. Чистый JS PNG работает везде",
